#!/bin/sh
# dump_router_keys.sh — dump the sec-engine key set (key0..key18) from a
# Nokia XS-2426-G (aarch64) for offline storage.
#
#   Run ON the router:   sh dump_router_keys.sh [output_dir]
#
# Why a harness and not a flash read: the stored keys live in the ENCRYPTED
# secdb (/tmp/sedb.conf, key6-sealed) and sec.key; the rest (key5/6/9/10/11/
# 15/16) are PBKDF2-derived at runtime. Nothing is plaintext in nvram/flash.
# So we ask the device's OWN sec engine: a tiny aarch64 LD_PRELOAD harness
# (embedded below, base64) whose constructor calls SE_Init()+SE_getKeyByName()
# for key0..18 and writes them to /tmp/keys.txt. We then bundle the key
# derivation sources (ritool + sechash) and a device manifest into a tarball.
#
# POSIX sh (busybox ash) compatible. Requires: the device's libsec_engine.so
# (present on every XS-2426G) and a base64 decoder (openssl/base64/busybox).
set -u
SELF="$0"

# ---------- locate the device sec engine (defines SE_Init/SE_getKeyByName) ----------
LIBSEC=""
for c in /usr/lib/libsec_engine.so /lib/libsec_engine.so; do
  [ -f "$c" ] && { LIBSEC="$c"; break; }
done
if [ -z "$LIBSEC" ]; then
  LIBSEC=$(ls /usr/lib/libsec_engine.so* /lib/libsec_engine.so* 2>/dev/null | head -1)
fi
[ -n "$LIBSEC" ] || { echo "ERROR: libsec_engine.so not found — not an XS-2426G, or sec engine absent." >&2; exit 1; }

# ---------- output location ----------
SERIAL=$(ritool get G984Serial 2>/dev/null | sed -n 's/.*[:=] *//p' | tr -dc 'A-Za-z0-9' | head -c 32)
[ -n "$SERIAL" ] || SERIAL="unknown"
STAMP=$(date +%Y%m%d-%H%M%S 2>/dev/null || echo now)
OUT="${1:-/tmp/keydump-${SERIAL}-${STAMP}}"
mkdir -p "$OUT" || { echo "ERROR: cannot create $OUT" >&2; exit 1; }

# ---------- extract the embedded harness (everything after the marker) ----------
SO="/tmp/.dumpkeys.$$.so"
B64="/tmp/.dk.$$.b64"
START=$(grep -n '^__DUMPKEYS_SO_B64__$' "$SELF" 2>/dev/null | head -1 | cut -d: -f1)
[ -n "$START" ] || { echo "ERROR: embedded harness marker not found in $SELF" >&2; exit 1; }
tail -n +$((START + 1)) "$SELF" > "$B64"

decode_ok=0
if command -v openssl >/dev/null 2>&1 && openssl base64 -d -A -in "$B64" -out "$SO" 2>/dev/null && [ -s "$SO" ]; then decode_ok=1
elif base64 -d "$B64" > "$SO" 2>/dev/null && [ -s "$SO" ]; then decode_ok=1
elif busybox base64 -d "$B64" > "$SO" 2>/dev/null && [ -s "$SO" ]; then decode_ok=1
fi
rm -f "$B64"
[ "$decode_ok" = 1 ] || { echo "ERROR: no working base64 decoder (need openssl/base64/busybox)." >&2; rm -f "$SO"; exit 1; }
chmod +x "$SO" 2>/dev/null

# ---------- run the harness: device sec engine -> key0..18 ----------
rm -f /tmp/keys.txt
LD_PRELOAD="$LIBSEC $SO" /bin/true 2>/dev/null
rm -f "$SO"
if [ ! -s /tmp/keys.txt ]; then
  echo "ERROR: key dump empty — SE_Init/SE_getKeyByName produced nothing." >&2
  echo "       (Try running as root; confirm $LIBSEC exports SE_getKeyByName.)" >&2
  exit 1
fi
mv /tmp/keys.txt "$OUT/keys.txt"

# ---------- key derivation sources (provenance / reproducibility) ----------
{
  echo "# key-derivation sources — $(date 2>/dev/null)"
  for k in G984Serial ProgDate Mnemonic LabelCode; do
    v=$(ritool get "$k" 2>/dev/null | sed -n 's/.*[:=] *//p' | head -1)
    printf '%s=%s\n' "$k" "$v"
  done
  # src5 = sechash over the mtd9 extfs security data
  sec_extfs -t sechash >/dev/null 2>&1
  for f in /tmp/.secHashStr /tmp/.ext_fwkey; do
    [ -f "$f" ] && printf 'sechash(%s)=%s\n' "$(basename "$f")" "$(cat "$f" 2>/dev/null)"
  done
} > "$OUT/sources.txt" 2>/dev/null

# ---------- device manifest ----------
{
  echo "model=$(cfgcli -g InternetGatewayDevice.DeviceInfo.ModelName 2>/dev/null | sed -n 's/.*=//p')"
  echo "serial=$SERIAL"
  echo "date=$STAMP"
  echo "brmac=$(cat /sys/class/net/br-lan/address 2>/dev/null)"
  echo "libsec=$LIBSEC"
  echo "keys_recovered=$(grep -cE '=[^(]' "$OUT/keys.txt" 2>/dev/null)"
  echo "keys_total=$(grep -c '=' "$OUT/keys.txt" 2>/dev/null)"
} > "$OUT/manifest.txt" 2>/dev/null

# ---------- tarball for storage ----------
TAR="$OUT.tar.gz"
( cd "$(dirname "$OUT")" && tar -czf "$TAR" "$(basename "$OUT")" 2>/dev/null ) && TARMSG="$TAR" || TARMSG="(tar failed; dir only)"

echo "[+] key dump complete"
echo "    dir:     $OUT"
echo "    tarball: $TARMSG"
echo "    keys:    $(grep -cE '=[^(]' "$OUT/keys.txt" 2>/dev/null)/$(grep -c '=' "$OUT/keys.txt" 2>/dev/null) recovered"
echo
echo "[!] This bundle contains DEVICE SECRETS. Pull it off the router, then delete on-device:"
echo "    (from your workstation)  scp root@<router>:$TARMSG ."
echo "    (on the router)          rm -rf \"$OUT\" \"$TAR\""
exit 0

# ---- embedded aarch64 dumpkeys.so (base64) follows the marker; do not edit ----
__DUMPKEYS_SO_B64__

